<?php
final class ApiV1 {
 public static function handle(string $method,string $path,array $p): mixed {
  Auth::load();SaasLegacyBoundary::enforce();if(Auth::$origin!=='api')fail('Use um token Bearer da API do TaskEsc.',401);
  $method=strtoupper($method);$write=in_array($method,['POST','PUT','PATCH','DELETE'],true);Auth::scope($write?'api.write':'api.read');
  $parts=array_values(array_filter(explode('/',trim($path,'/')),'strlen'));
  if(!$parts)return self::index();
  if($parts[0]==='status'&&$method==='GET')return ['ok'=>true,'service'=>'TaskEsc API','version'=>'v1','time'=>now()];
  if($parts[0]==='me'&&$method==='GET')return ['user'=>Auth::$user,'scopes'=>preg_split('/\s+/',trim(Auth::$scopes))];
  if($parts[0]==='meta'&&$method==='GET')return Catalog::meta();
  if($parts[0]==='analysis'&&($parts[1]??'')==='overview'&&$method==='GET')return self::analysis($p);
  if($parts[0]==='kanban'&&$method==='GET')return ['stages'=>DB::all('SELECT * FROM stages WHERE active=1 ORDER BY position,id'),'tasks'=>Demands::list(array_merge(['include_closed'=>1],$p))];
  if($parts[0]==='tasks')return self::tasks($method,$parts,$p);
  if($parts[0]==='clients')return self::clients($method,$parts,$p);
  if($parts[0]==='calendar')return self::calendar($method,$parts,$p);
  if($parts[0]==='finance')return self::finance($method,$parts,$p);
  if($parts[0]==='reports'&&$method==='GET'){Auth::admin();$type=$parts[1]??($p['type']??'production');return Reports::report(['type'=>$type]+$p);}
  if($parts[0]==='users')return self::users($method,$parts,$p);
  fail('Rota da API não encontrada.',404);
 }
 private static function index(): array {return ['name'=>'TaskEsc API','version'=>'v1','openapi'=>base('openapi.json'),'endpoints'=>['GET /api/v1/status','GET /api/v1/analysis/overview','GET|POST /api/v1/tasks','GET|PATCH|PUT|DELETE /api/v1/tasks/{id}','POST /api/v1/tasks/{id}/move','POST /api/v1/tasks/{id}/comments','GET /api/v1/tasks/{id}/files','DELETE /api/v1/tasks/{id}/files/{file_id}','GET|POST /api/v1/clients','GET|PATCH|PUT|DELETE /api/v1/clients/{id}','GET|POST /api/v1/calendar/events','GET|PATCH|PUT|DELETE /api/v1/calendar/events/{id}','GET /api/v1/finance/summary','GET /api/v1/finance/invoices','GET /api/v1/finance/receivables','GET /api/v1/finance/expenses','GET /api/v1/reports/{type}','GET|POST /api/v1/users','GET|PATCH|PUT|DELETE /api/v1/users/{id}']];}
 private static function tasks(string $method,array $parts,array $p): mixed {
  $id=isset($parts[1])&&ctype_digit((string)$parts[1])?(int)$parts[1]:0;
  if(!$id){if($method==='GET')return TaskEscTaskApi::list($p);if($method==='POST')return TaskEscTaskApi::create($p);fail('Método não permitido.',405);}
  if(isset($parts[2])){if($parts[2]==='move'&&$method==='POST'){$d=Auth::demand($id);return TaskEscTaskApi::move(['id'=>$id,'version'=>$p['version']??$d['version'],'stage_id'=>$p['stage_id']??0,'sort_order'=>$p['sort_order']??0]);}if($parts[2]==='comments'){if($method==='GET')return Demands::get(['id'=>$id])['comments'];if($method==='POST')return Demands::comment(['demand_id'=>$id]+$p);}if($parts[2]==='files'){if($method==='GET')return Demands::get(['id'=>$id])['files'];if($method==='DELETE'&&isset($parts[3])&&ctype_digit((string)$parts[3])){Auth::demand($id);$f=DB::one('SELECT id,demand_id FROM files WHERE id=? AND demand_id=?',[(int)$parts[3],$id]);if(!$f)fail('Anexo não encontrado.',404);return Files::delete(['file_id'=>(int)$parts[3]]);}}fail('Rota da task não encontrada.',404);}
  if($method==='GET')return Demands::get(['id'=>$id]);
  if(in_array($method,['PATCH','PUT'],true)){$d=Demands::get(['id'=>$id]);$payload=['id'=>$id,'version'=>$d['version'],'client_id'=>$d['client_id'],'category_id'=>$d['category_id'],'title'=>$d['title'],'brief'=>$d['brief'],'due_at'=>str_replace(' ','T',(string)$d['due_at']).'Z','priority'=>$d['priority'],'assigned_to'=>$d['assigned_to'],'billing_mode'=>$d['billing_mode'],'amount_cents'=>$d['amount_cents']??0,'commercial_status'=>$d['commercial_status'],'draft'=>$d['draft']]; $payload=array_merge($payload,$p);return TaskEscTaskApi::update($payload);}
  if($method==='DELETE')return Demands::delete(['id'=>$id]);fail('Método não permitido.',405);
 }
 private static function clients(string $method,array $parts,array $p): mixed {Auth::admin();$id=isset($parts[1])&&ctype_digit((string)$parts[1])?(int)$parts[1]:0;if(!$id){if($method==='GET')return Catalog::clients($p);if($method==='POST')return Catalog::clientSave($p);fail('Método não permitido.',405);}if($method==='GET')return Auth::client($id);if(in_array($method,['PATCH','PUT'],true)){$c=Auth::client($id);return Catalog::clientSave(array_merge(['id'=>$id,'name'=>$c['name']],$p));}if($method==='DELETE')return Catalog::clientDelete(['id'=>$id]);fail('Método não permitido.',405);}
 private static function calendar(string $method,array $parts,array $p): mixed {Auth::admin();if(($parts[1]??'')!=='events')fail('Rota de agenda não encontrada.',404);$id=isset($parts[2])&&ctype_digit((string)$parts[2])?(int)$parts[2]:0;if(!$id){if($method==='GET')return Agenda::list($p);if($method==='POST')return Agenda::save($p);fail('Método não permitido.',405);} $e=DB::one('SELECT * FROM events WHERE id=?',[$id]);if(!$e)fail('Compromisso não encontrado.',404);if($method==='GET')return $e;if(in_array($method,['PATCH','PUT'],true))return Agenda::save(array_merge(['id'=>$id,'version'=>$e['version'],'calendar_id'=>$e['calendar_id'],'title'=>$e['title'],'starts_at'=>str_replace(' ','T',(string)$e['starts_at']).'Z','ends_at'=>str_replace(' ','T',(string)$e['ends_at']).'Z','location'=>$e['location'],'description'=>$e['description'],'buffer_minutes'=>$e['buffer_minutes'],'private'=>$e['private'],'all_day'=>$e['all_day'],'demand_id'=>$e['demand_id']],$p));if($method==='DELETE')return Agenda::cancel(['id'=>$id,'version'=>$e['version']]);fail('Método não permitido.',405);}
 private static function finance(string $method,array $parts,array $p): mixed {Auth::admin();if($method!=='GET')fail('Use os endpoints específicos de pagamento do painel para escritas financeiras.',405);if(($parts[1]??'summary')==='receivables')return TaskEscFinanceReadApi::receivables($p);if(($parts[1]??'summary')==='expenses')return TaskEscFinanceReadApi::expenses($p);if(($parts[1]??'summary')==='invoices')return Finance::invoices($p);$d=Reports::dashboard($p);return ['period'=>$d['period'],'financial'=>$d['financial'],'monthly_clients'=>Finance::monthlyClients()];}
 private static function users(string $method,array $parts,array $p): mixed {Auth::admin();$id=isset($parts[1])&&ctype_digit((string)$parts[1])?(int)$parts[1]:0;if(!$id){if($method==='GET')return Catalog::users();if($method==='POST')return Catalog::userSave($p);fail('Método não permitido.',405);}if($method==='GET'){foreach(Catalog::users() as $u)if((int)$u['id']===$id)return $u;fail('Usuário não encontrado.',404);}if(in_array($method,['PATCH','PUT'],true)){$old=DB::one('SELECT id,name,email,role,active,email_notifications FROM users WHERE id=?',[$id]);if(!$old)fail('Usuário não encontrado.',404);$old['clients']=DB::all('SELECT client_id,can_approve,can_finance FROM user_clients WHERE user_id=?',[$id]);return Catalog::userSave(array_merge($old,['id'=>$id],$p));}if($method==='DELETE'){if($id===(int)Auth::$user['id'])fail('Não é possível desativar o próprio usuário.',409);$u=DB::one('SELECT * FROM users WHERE id=?',[$id]);if(!$u)fail('Usuário não encontrado.',404);DB::update('users',$id,['active'=>0]);audit('user',$id,'deactivated',$u,['active'=>0]);return ['deleted'=>true,'id'=>$id];}fail('Método não permitido.',405);}
 private static function analysis(array $p): array {Auth::admin();$dashboard=Reports::dashboard($p);$overdue=Demands::list(['overdue'=>1,'include_closed'=>1]);$clients=DB::all("SELECT c.id,c.name,c.commercial_type,c.monthly_amount_cents,c.monthly_payment_day,COALESCE(SUM(CASE WHEN d.id IS NOT NULL AND s.kind NOT IN ('completed','cancelled','archived') THEN 1 ELSE 0 END),0) AS open_tasks FROM clients c LEFT JOIN demands d ON d.client_id=c.id AND d.deleted_at IS NULL LEFT JOIN stages s ON s.id=d.stage_id WHERE c.active=1 GROUP BY c.id ORDER BY open_tasks DESC,c.name LIMIT 100");return ['generated_at'=>now(),'dashboard'=>$dashboard,'overdue_tasks'=>$overdue,'clients'=>$clients,'notes'=>['financial_values_are_cents'=>true,'timezone'=>config('timezone')]];}
}
